package org.usbworkbench;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.security.*;

/** Bounded basic-partition table conversion; filesystem sectors are never moved or written. */
public final class PartitionConversion {
 static final UUID BASIC=UUID.fromString("EBD0A0A2-B9E5-4433-87C0-68B6B72699C7"),LINUX=UUID.fromString("0FC63DAF-8483-4772-8E79-3D69D8477DE4"),EFI=UUID.fromString("C12A7328-F81F-11D2-BA4B-00A0C93EC93B"),SWAP=UUID.fromString("0657FD6D-A4AB-43C4-84E5-0933C84B4F4F");
 public static final class Part {public final long start,end;final byte[] type;final int mbrType;final String name;Part(long s,long e,byte[] t,int m,String n){start=s;end=e;type=t;mbrType=m;name=n;}}
 public static final class Plan {public final boolean gpt;public final List<Part> parts;final byte[] mbr;final long sectors;Plan(boolean g,List<Part> p,byte[] b,long n){gpt=g;parts=Collections.unmodifiableList(p);mbr=b;sectors=n;}}
 private static byte[] sector(BlockDevice d,long at)throws IOException{byte[] b=new byte[512];d.read(at,b,512);return b;}
 public static Plan read(BlockDevice d)throws IOException {
  if(d.blockSize()!=512||d.blockCount()<4096||d.blockCount()>0xffffffffL)throw new IOException("TABLE_GEOMETRY");byte[] mbr=sector(d,0);if(mbr[510]!=85||(mbr[511]&255)!=170)throw new IOException("TABLE_UNSUPPORTED");boolean gpt=(mbr[450]&255)==238;List<Part> parts=new ArrayList<>();
  if(gpt){AdvancedDiskTools.inspectGpt(d);byte[] h=sector(d,1);if(OpticalImage.u32(h,80)!=128||OpticalImage.u32(h,84)!=128||OpticalImage.u64(h,72)!=2||OpticalImage.u64(sector(d,d.blockCount()-1),72)!=d.blockCount()-33)throw new IOException("TABLE_UNSUPPORTED");byte[] entries=new byte[16384];d.read(2,entries,entries.length);for(int i=0;i<128;i++){int at=i*128;byte[] type=Arrays.copyOfRange(entries,at,at+16);boolean empty=true;for(byte b:type)if(b!=0)empty=false;if(empty)continue;if(OpticalImage.u64(entries,at+48)!=0)throw new IOException("TABLE_ATTRIBUTES");String name=new String(entries,at+56,72,StandardCharsets.UTF_16LE).split("\u0000",2)[0];parts.add(new Part(OpticalImage.u64(entries,at+32),OpticalImage.u64(entries,at+40),type,0,name));}}
  else for(int i=0;i<4;i++){int at=446+i*16,type=mbr[at+4]&255;long start=OpticalImage.u32(mbr,at+8),count=OpticalImage.u32(mbr,at+12);if(type==0){if(start!=0||count!=0)throw new IOException("TABLE_UNSUPPORTED");continue;}if(count<1)throw new IOException("TABLE_UNSUPPORTED");UUID guid=type==0x83?LINUX:type==0x82?SWAP:type==0xef?EFI:(type==1||type==6||type==7||type==0xb||type==0xc||type==0xe)?BASIC:null;if(guid==null)throw new IOException("TABLE_UNSUPPORTED");parts.add(new Part(start,start+count-1,AdvancedDiskTools.guid(guid),type,"USB "+(i+1)));}
  if(parts.isEmpty())throw new IOException("TABLE_EMPTY");List<Part> ordered=new ArrayList<>(parts);Collections.sort(ordered,(a,b)->Long.compare(a.start,b.start));long previous=2047;for(Part part:ordered){if(part.start<=previous||part.end<part.start||part.end>=d.blockCount())throw new IOException("TABLE_NO_ROOM");previous=part.end;byte[] boot=sector(d,part.start);if(new String(boot,3,8,StandardCharsets.US_ASCII).equals("-FVE-FS-")||boot[0]=='L'&&boot[1]=='U'&&boot[2]=='K'&&boot[3]=='S'&&(boot[4]&255)==186&&(boot[5]&255)==190)throw new IOException("TABLE_ENCRYPTED");}
  return new Plan(gpt,parts,mbr,d.blockCount());
 }
 public static void validateTarget(Plan plan,String target)throws IOException{if(!target.equals("mbr")&&!target.equals("gpt"))throw new IOException("FORMAT_OPTIONS");if(plan.gpt==target.equals("gpt"))throw new IOException("TABLE_ALREADY");if(target.equals("gpt"))for(Part part:plan.parts)if(part.end>=plan.sectors-33)throw new IOException("TABLE_NO_ROOM");if(target.equals("mbr")){if(plan.parts.size()>4)throw new IOException("TABLE_TOO_MANY");for(Part p:plan.parts)if(!Arrays.equals(p.type,AdvancedDiskTools.guid(BASIC))&&!Arrays.equals(p.type,AdvancedDiskTools.guid(LINUX))&&!Arrays.equals(p.type,AdvancedDiskTools.guid(EFI))&&!Arrays.equals(p.type,AdvancedDiskTools.guid(SWAP)))throw new IOException("TABLE_UNSUPPORTED");}}
 public static byte[] backup(BlockDevice d,Plan plan)throws IOException {ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeBytes("USBPT001");out.writeLong(d.blockCount());out.writeInt(512);out.writeInt(plan.gpt?67:34);for(int i=0;i<34;i++){out.writeLong(i);out.write(sector(d,i));}if(plan.gpt)for(long i=d.blockCount()-33;i<d.blockCount();i++){out.writeLong(i);out.write(sector(d,i));}}byte[] payload=bytes.toByteArray();try{MessageDigest sha=MessageDigest.getInstance("SHA-256");bytes.write(sha.digest(payload));}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}return bytes.toByteArray();}
 public static void convert(BlockDevice d,Plan plan,String target,DiskTools.Progress p)throws IOException{
  validateTarget(plan,target); // All unsupported cases fail before writes.
  Plan current=read(d);if(plan.sectors!=d.blockCount()||current.gpt!=plan.gpt||!Arrays.equals(current.mbr,plan.mbr)||current.parts.size()!=plan.parts.size())throw new IOException("DEVICE_CHANGED");for(int i=0;i<plan.parts.size();i++){Part a=plan.parts.get(i),b=current.parts.get(i);if(a.start!=b.start||a.end!=b.end||!Arrays.equals(a.type,b.type))throw new IOException("DEVICE_CHANGED");}
  BlockDevice checked=VentoyInstaller.verified(d);long last=d.blockCount()-1;byte[] mbr=plan.mbr.clone();Arrays.fill(mbr,446,510,(byte)0);p.update(0,3);
  if(target.equals("gpt")){byte[] entries=new byte[16384];for(int i=0;i<plan.parts.size();i++){Part part=plan.parts.get(i);int at=i*128;System.arraycopy(part.type,0,entries,at,16);System.arraycopy(AdvancedDiskTools.guid(UUID.randomUUID()),0,entries,at+16,16);AdvancedDiskTools.le64(entries,at+32,part.start);AdvancedDiskTools.le64(entries,at+40,part.end);byte[] label=part.name.getBytes(StandardCharsets.UTF_16LE);System.arraycopy(label,0,entries,at+56,Math.min(label.length,72));}byte[] id=AdvancedDiskTools.guid(UUID.randomUUID());long crc=AdvancedDiskTools.crc(entries,entries.length);p.update(0,3);checked.write(last-32,entries,entries.length);checked.write(last,AdvancedDiskTools.gptHeader(last,1,last-32,last,id,crc),512);p.update(1,3);checked.write(2,entries,entries.length);checked.write(1,AdvancedDiskTools.gptHeader(1,last,2,last,id,crc),512);mbr[450]=(byte)238;mbr[448]=2;Arrays.fill(mbr,451,454,(byte)255);DiskTools.le32(mbr,454,1);DiskTools.le32(mbr,458,last);}
  else {int i=0;for(Part part:plan.parts){int at=446+16*i++,type=Arrays.equals(part.type,AdvancedDiskTools.guid(LINUX))?0x83:Arrays.equals(part.type,AdvancedDiskTools.guid(EFI))?0xef:Arrays.equals(part.type,AdvancedDiskTools.guid(SWAP))?0x82:7;if(type==7){byte[] boot=sector(d,part.start);if(new String(boot,82,8,StandardCharsets.US_ASCII).equals("FAT32   "))type=0xc;else if(new String(boot,54,8,StandardCharsets.US_ASCII).equals("FAT16   "))type=0xe;else if(new String(boot,54,8,StandardCharsets.US_ASCII).equals("FAT12   "))type=1;}mbr[at+1]=mbr[at+5]=(byte)254;mbr[at+2]=mbr[at+3]=mbr[at+6]=mbr[at+7]=(byte)255;mbr[at+4]=(byte)type;DiskTools.le32(mbr,at+8,part.start);DiskTools.le32(mbr,at+12,part.end-part.start+1);}byte[] zero=new byte[512];for(long at=last-32;at<=last;at++){p.update(1,3);checked.write(at,zero,512);}for(long at=1;at<34;at++){p.update(1,3);checked.write(at,zero,512);}}
  mbr[510]=85;mbr[511]=(byte)170;checked.sync();p.update(2,3);checked.write(0,mbr,512);checked.sync();Plan after=read(d);if(after.gpt!=target.equals("gpt")||after.parts.size()!=plan.parts.size())throw new IOException("VERIFY_FAILED");p.update(3,3);
 }
}
